static uint32_t operation(uint32_t op,uint32_t a,uint32_t b){uint32_t r=0;switch(op){
case 0:__asm__ volatile(".insn r 0x33,0,1,%0,%1,%2":"=r"(r):"r"(a),"r"(b));break;
case 1:__asm__ volatile(".insn r 0x33,1,1,%0,%1,%2":"=r"(r):"r"(a),"r"(b));break;
case 2:__asm__ volatile(".insn r 0x33,2,1,%0,%1,%2":"=r"(r):"r"(a),"r"(b));break;
case 3:__asm__ volatile(".insn r 0x33,3,1,%0,%1,%2":"=r"(r):"r"(a),"r"(b));break;
case 4:__asm__ volatile(".insn r 0x33,4,1,%0,%1,%2":"=r"(r):"r"(a),"r"(b));break;
case 5:__asm__ volatile(".insn r 0x33,5,1,%0,%1,%2":"=r"(r):"r"(a),"r"(b));break;
case 6:__asm__ volatile(".insn r 0x33,6,1,%0,%1,%2":"=r"(r):"r"(a),"r"(b));break;
case 7:__asm__ volatile(".insn r 0x33,7,1,%0,%1,%2":"=r"(r):"r"(a),"r"(b));break;
}return r;}
static void hex(const cpu_bench_api *p,uint32_t v){for(int i=7;i>=0;i--)p->putc("0123456789abcdef"[(v>>(i*4))&15u]);}
int bench_entry_c(const cpu_bench_api *p,uint32_t iterations,uint32_t validation){(void)iterations;(void)validation;uint32_t failures=0,hash=0; if(!(p->misa()&(1u<<12)))return 1;
for(uint32_t i=0;i<sizeof(vectors)/sizeof(vectors[0]);i++){for(uint32_t op=0;op<8;op++){uint32_t got=operation(op,vectors[i][0],vectors[i][1]);if(got!=vectors[i][op+2]){failures++;if(failures==1){const char*s="@M_FIRST ";while(*s)p->putc(*s++);hex(p,i);p->putc(32);hex(p,op);p->putc(32);hex(p,got);p->putc(32);hex(p,vectors[i][op+2]);p->putc(13);p->putc(10);}}hash=(hash<<1)^(hash>>31)^got;}
uint32_t a=vectors[i][0],b=vectors[i][1],raw;__asm__ volatile(".insn r 0x33,0,1,t0,%1,%2; add %0,t0,%1":"=r"(raw):"r"(a),"r"(b):"t0");if(raw!=vectors[i][2]+a)failures++;
uint32_t alias=a;__asm__ volatile(".insn r 0x33,0,1,%0,%0,%1":"+r"(alias):"r"(b));if(alias!=vectors[i][2])failures++;
uint32_t divdep;__asm__ volatile(".insn r 0x33,4,1,t0,%1,%2; add %0,t0,%1":"=r"(divdep):"r"(a),"r"(b):"t0");if(divdep!=vectors[i][6]+a)failures++;}
const char*s="@M_TEST ";while(*s)p->putc(*s++);hex(p,sizeof(vectors)/sizeof(vectors[0]));p->putc(32);hex(p,failures);p->putc(32);hex(p,hash);p->putc(13);p->putc(10);return failures!=0;}
